"""Final bond reviews preserving original questions and scoped evidence."""

REVIEWS = []


def concept(key, answer, prompt, proof, assumptions, finding="", claims="", kind="text"):
    """Save one scoped review, including its own derivation and source correction."""
    REVIEWS.append({
        "id": key, "answer": answer, "clean_prompt": prompt,
        "claim_ids": claims.split(), "review_note": proof,
        "source_finding": finding, "answer_kind": kind,
        "concept_review": {"derivation": proof, "assumptions": assumptions,
                           "basis": "explicit_conditions_and_independent_reasoning",
                           "current_law_claim": False},
    })


def mc(key, answer, prompt, proof, assumptions, finding="", claims=""):
    """Use the same evidence requirements for a multiple-choice review."""
    concept(key, answer, prompt, proof, assumptions, finding, claims, kind="multiple_choice")

mc("S3C5T03-SUP-02", "③", "정기 재설정일마다 쿠폰이 기준금리+고정가산금리로 바뀌는 보통 FRN과, 쿠폰이 K-기준금리인 역변동채를 비교한다. 옵션상하한이 작동하지 않는 범위이며 신용스프레드는 일정하다. 틀린 것은? ①전자와 같은 쿠폰구조는 FRN이다. ②후자는 역변동금리채다. ③매 재설정 직후 기준금리와 할인금리가 같고 가산금리0인 FRN도 잔존만기만큼의 고정금리채와 같은 큰 가격민감도를 갖는다. ④역변동채는 재설정 기준금리가 높아지면 다음 쿠폰현금흐름이 감소한다.", "①미재무부FRN의지표+스프레드구조로확인.②④K-r의미분은-1이다.③재설정직후무스프레드변동채는가격이액면으로재설정되며다음재설정까지의짧은금리노출이주요하므로고정금리장기채와같다는주장은틀리다. 시장금리즉시변동/스프레드변동때가격이절대불변이라는뜻아님.", "TARGET258쪽4보기전체직접확인.③시장금리반영이라는쿠폰/가격혼동을가격민감도로한정;동일통화·부도없음·할인과기준일치.", "원문③은쿠폰이시장금리를반영한다는참인해석도가능하므로가격민감도를명시. 원해설의정기조정이기때문에덜민감하다는인과설명은조정빈도증가시금리노출이짧아진다는관계로바로잡았다. LIBOR예시를현재지표로일반화하지않음.", "FB005")
mc("S3C5T03-SUP-03", "③", "국내 회사채 장기신용등급에서 투자적격등급 중 최하위 세부등급은? ①AA+ ②A0 ③BBB- ④BB+", "투자등급경계가BBB-/BB+이므로③. 원문258쪽실제이미지②A0확인.", "국내회사채장기신용등급관행. 법률별투자가능등급기준과구분.", "원해설의각등급모두가+0-로분할된다는주장은오류이며AA부터B까지만+/-구분. 원문4보기·답③그대로유지.", "FB001")
mc("S3C5T06-SUP-03", "①", "국고채 유동성과 거래연속성을 높이기 위해 만기일과 표면금리가 동일한 종목을 반복발행하는 제도로 2000년5월 도입된 것은? ①국채통합발행제도 ②국고채 원금·이자 분리제도 ③물가연동국고채권 발행제도 ④국채전문유통시장", "재정경제부국채시장공식통합발행설명과연혁에서2000년5월동일만기일·표면금리통합확인. STRIPS/물가연동/유통시장과구별되므로①.", "TARGET267쪽전체보기·정답·해설대조;역사적도입일과제도정의만검증.", "OCR200이년을2000년으로복원. 원문4보기와정답유지.", "FB002")
mc("S3C5T07-SUP-01", "④", "2026-10-13 기준 국고채전문딜러(PD)의 지정·의무 설명 중 옳은 것을 모두 고르면? 가.국채 투자매매업(인수업포함)인가자 중 PPD선행 및 지정요건을 충족하여 재정경제부장관의 지정을 받는다. 나.규정30조의 기본 인수의무는 매월 각 만기별 공고상 발행예정물량의8%이상이며 인수실적산정특례와장관의비율조정권한이있다. 다.매분기 딜링용 국고채보유 평균잔액을1조원이상 유지하며 추종ETF는평균잔액1000억원한도에서포함한다. ①가 ②가·나 ③나·다 ④가·나·다", "국고채발행규정2조·29조로가,30조로기본8%와산정/조정조건나,34조로분기평균1조원과ETF한도다를각각확인하여④.", "2026-02-23시행규정;TARGET269쪽가나다와4조합모두보존.장관이별도로조정한실제당월인수비율단정은안함.", "원문의기획재정부→재정경제부,10%→규정기본8%를교정하고분기평균및ETF한도와PPD선행을보완. 해설의호가·유통·매입교환다른의무는이문항정답의근거로일괄승인하지않음.", "FB003")

mc("S3C5T10-CORE", "④", "옵션·부도위험이 없는 연1회 고정쿠폰채를 쿠폰지급 직후 비교한다. 만기만 다른 채권들의 액면·쿠폰율c·최초수익률y0=c>0는 같고 처음에는 모두 액면가격이다. 변화 후 수익률도 양수이고 같은 폭으로 변한다. 틀린 것은? ①가격과 수익률은 역관계다. ②같은 수익률변화에서 장기채의 가격변동폭이 더 크다. ③그 변동폭의 만기에 따른 증가분은 체감한다. ④같은 채권에 대해 동일폭 수익률 상승의 가격하락폭이 하락의 가격상승폭보다 크다.", "액면1이면 P_n(y)=c/y+(1-c/y)(1+y)^(-n). P_n(c)=1이므로 변동폭은 |1-c/y|[1-(1+y)^(-n)]이고 y>0에서n에따라증가하며차분은체감한다. P′<0, P″=Σt(t+1)CF_t/(1+y)^(t+2)>0이므로동일폭h에서P(y-h)-P(y)>P(y)-P(y+h).④가반대다.", "TARGET274쪽4보기전체보존. 초기액면가격·동일쿠폰·양의수익률·고정현금흐름으로말킬만기비교의성립범위명시.", "원문의무조건장기채/만기체감진술은극단할인채등에일반화할수없으므로동일초기액면조건보완. 금리변동폭은동일하며가격절대변동/변동률은초기가격같아동일순위.")
mc("S3C5T10-SUP-01", "④", "옵션없는연1회쿠폰·만기5년·액면100의두채권은쿠폰율만4%와8%로다르다. 수익률이6%에서8%로2%p상승할때 가격은 각각91.5753→84.0292(-8.2403%),108.4247→100(-7.7701%)이다. 이 표에서 쿠폰차이에 따른 가격변동률 차이를 직접 설명하는 성질은? ①가격과수익률역관계 ②만기증가에따른가격변동폭체감증가 ③동일폭금리하락의상승폭이금리상승의하락폭보다큼 ④쿠폰율이높을수록같은수익률변화에대한가격변동률이작음", "P=Σ4/(1+y)^t+100/(1+y)^5 및쿠폰8의동일식으로각가격재계산. 변화율은-8.24033866%와-7.77011643%이다. 비교하는독립변수는쿠폰이며만기와금리변화는동일하므로④.", "TARGET275쪽원래쿠폰4/8와금리변화2%p·4보기보존. 만기5년/초기수익률6%를추가하여표재계산.", "원문2%/쿠폰율=50%,25%는채권가격변동률공식이아니다. 잘못된표수치만DCF로교정하고쿠폰민감도판단목적유지. 절대가격변화가아닌가격변동률로명시.")
mc("S3C5T10-SUP-02", "④", "기준채권은옵션없는만기5년·액면100·연1회쿠폰율5%·연수익률5%이고쿠폰직후평가한다. 각보기는기준에서독립적으로한조건만바꾼다. 맥컬리듀레이션이길어지지않는것은? ①쿠폰율3%로하락 ②만기10년으로증가 ③수익률3%로하락 ④연명목쿠폰/수익률5%를유지하고반년마다쿠폰지급·복리할인", "PV가중평균시점D=ΣtPV(CF_t)/P로직접계산하면기준4.5459505년,①4.7017445,②8.1078217,③4.5680605,④4.4854328년이므로④만감소.④는반년쿠폰2.5,반년할인2.5%,10회.", "TARGET275쪽쿠폰/만기/수익률/지급횟수4주제와정답보존. 비교조건을수치로명시하여만기일반화반례배제.", "원문의모든채권에무조건만기와D증가단정을조건부비교로보완. 지급횟수만늘리고연쿠폰까지증가시키지않도록연명목기준명시.")
mc("S3C5T11-SUP-04", "④", "첫쿠폰이1년뒤부터매년같은양의금액으로영구히지급되는옵션없는영구채의연복리수익률은5%다. 맥컬리듀레이션은? ①5년 ②10년 ③20년 ④21년", "P=C/y, 시간가중PV합=C(1+y)/y²이므로D=(1+y)/y=1.05/.05=21년. 수정D=D/(1+y)=20년과구별하여④.", "TARGET278쪽4숫자보기보존;연1회후급고정쿠폰·양의수익률.", "원문에생략된쿠폰주기와맥컬리정의를명시.")
mc("S3C5T14-SUP-01", "①", "채권투자위험 설명 중 틀린 것은? ①일반회사채는만기보유만하면원리금지급이항상보장되고그동안시장가격도변동하지않는다. ②같은발행자의보통주보다청구순위가높은일반선순위채권이라도발행자가원리금을지급하지못할신용위험이있다. ③필요할때적정가치에매도하기어려운위험은유동성위험이다. ④발행자에게콜권리가있는채권이금리하락기에조기상환되면높은쿠폰지속수취기회를잃고같은위험에서더낮은금리로재투자할수있다.", "만기보유는발행자의부도가능성을제거하지않으며시장금리와신용스프레드가바뀌면중간평가가격도변한다.③유동성과④콜/재투자위험은SEC정의와일치한다.②는일반선순위청구권범위로한정하며모든채권이모든주식보다안전하다는뜻아님.①이틀리다.", "TARGET288쪽보증·신용·유동성·콜4보기보존. 콜조항있음,고정명목급부.", "원문②채권이주식보다항상안전하다는일반화는같은발행자의선순위청구권으로최소교정.④는모든중도상환이무조건손해라는단정을금리하락콜에따른기회/재투자위험으로정확화.", "FB006")
mc("S3C5T14-SUP-02", "②", "발행자로부터원리금전부또는일부를받지못할위험과,투자중물가상승으로명목원리금의구매력이하락할위험을순서대로고르면? ①채무불이행위험·이자율변동위험 ②채무불이행위험·구매력위험 ③중도상환위험·구매력위험 ④중도상환위험·재투자위험", "원리금미지급은default risk,명목현금흐름의실질구매력감소는inflation risk이므로②. 이자율위험/콜/재투자와구분.", "TARGET289쪽두정의와4조합전체보존.", "", "FB006")
mc("S3C5T14-SUP-03", "①", "다른요인이같고기대단기금리평균성분은만기와관계없이일정하다고하자. 장기일수록더높아지는유동성프리미엄을요구하여 y(T)=일정기대금리+증가하는프리미엄(T)으로정하는경우수익률곡선은? ①우상향 ②우하향 ③낙타형 ④수평형", "만기증가때상수기대성분의차이는0이고프리미엄차이는양수이므로y(T2)>y(T1).①.", "TARGET289쪽유동성프리미엄과4모양보존. 기대금리성분일정이라는필요조건명시.", "원문은금리하락기대가프리미엄증가보다클때우하향할수있다는조건을누락했다. 무조건우상향을기대금리일정하의조건부결론으로교정.")
mc("S3C5T17-SUP-01", "④", "옵션없는연1회쿠폰채들의현재수익률은모두5%이고신용·유동성·비용조건이같다. 아주작은동일폭금리상승직후가격손실률을1차듀레이션으로최소화하려면? ①쿠폰3%·만기10년 ②쿠폰5%·만기5년 ③쿠폰5%·만기3년 ④쿠폰7%·만기3년", "각현금흐름을5%할인하여수정D를계산하면①8.2450854,②4.3294767,③2.7232480,④2.6793724. ΔP/P≈-DmodΔy에서④손실률최소.", "TARGET300쪽4쿠폰/만기조합보존. 공통현재수익률5%,작은금리변동,고정현금흐름.", "원문어떤상황에도가장유리라는말을금리변화직후가격손실률목적으로한정. 보유기간총수익/신용/비용/큰금리변화까지보장하지않음.")
mc("S3C5T17-SUP-02", "④", "3년국채수익률4%,같은만기회사채7%다. 경기호황전환과함께국채수익률은그대로이고해당회사채신용스프레드는축소될것으로전망하며부도·유동성·비용및금리위험은별도로통제한다. 이견해에맞춰상대적으로더높은이자를취하는교체전략과명칭은? ①국채매수·Yield Give Up Swap ②국채매수·Yield Pick Up Swap ③회사채매수·Yield Give Up Swap ④회사채매수·Yield Pick Up Swap", "국채를줄이고7%회사채를사는것은4%→7%의수익률증대를추구하므로yield pick up이다. 회사채요구수익률이국채금리고정하에내리면그가격은오른다.④.", "TARGET300~301쪽누락질문을앞packet연속본문으로복원.4보기보존. 스프레드축소는명시적예상이며경기국면만으로보장안함.", "단순호황이면항상크레딧수익보장이라는해설확대를배제하고회사채스프레드축소예상조건을명시.")
mc("S3C5T17-SUP-04", "④", "다음은명시된조건하의채권전략설명이다. 틀린것은? ①경기호전과함께신용스프레드축소를예상하고추가위험을감수한다면낮은수익률국채를높은수익률회사채로교체하는Yield Pick Up을고려한다. ②스프레드현재4%,평균2%,표준편차.5%면z지수는4다. ③다른조건이같고중기수익률만상대적으로더크게하락할전망에서는중기노출을집중하는Bullet이그견해에부합한다. ④공통양의수익률y에서만기T무이표Bullet과,같은현재가치·듀레이션T를가지도록T보다짧고긴무이표채로구성한Barbell을비교하면Barbell의볼록성이더낮다.", "②(4-2)/.5=4.③중기채가격이상대적으로상승하는노출을선택.④무이표채C=t(t+1)/(1+y)²이며PV가중평균t=T인바벨C는[T²+T+Var(t)]/(1+y)²이므로Bullet보다Var(t)/(1+y)²>0크다.따라서④틀림.", "TARGET301쪽4주제PickUp/z/Bullet/Barbell모두보존. 바벨우위에는동일PV·동일D·동일y·고정양현금흐름조건필요.", "바벨이항상모든Bullet보다높은볼록성이라는무조건명제를동일평균시점에서의분산증가비교로교정. 경기사이클과신용스프레드는기계적인필연관계로승인하지않음.")

mc("S3C5T17-CORE", "③", "그림은시간이지나도형태가유지되는우상향수익률곡선이다. ΔA는장기구간,ΔB는중단기급경사구간에서잔존만기감소에따른수익률하락을나타낸다. 교재용어로ΔA를롤링,ΔB를숄더효과라부른다. 고정현금흐름채권의시간경과·쿠폰·액면수렴효과를분리하고수익률변화에따른가격효과만논한다. 틀린것은? ①잔존만기가짧아질때곡선을따라수익률이낮아지는부분은가격상승에기여한다. ②그림의ΔA/ΔB같은롤다운수익률하락을얻으려면해당구간이우상향이어야한다. ③다른조건이같은금리의추가평행하락은이수익률하락효과를반대로뒤집는다. ④교재에서ΔA의효과는롤링효과라부른다.", "우상향곡선y(T)에서시간경과h는잔존만기T-h<T,따라서y(T-h)<y(T). 고정현금흐름가격의수익률미분이음수이므로이수익률하락부분은가격상승기여다. 추가금리하락은이를강화하므로③틀림. 금리상승이롤다운폭보다크면효과를상쇄할수있지만아주작은상승이라고항상총손실인것은아님.", "TARGET298·299쪽실제도표전체확인. ΔA장기/ΔB중단기명칭은교재정의로한정. 부도·옵션·스프레드변동없음.", "원문①과해설은쿠폰채의가격이시간경과만으로항상오른다거나금리상승이면반드시손실이라고단정해가격효과와총보유수익을혼동.4보기와ΔA/ΔB도표의도를보존하며순수롤다운기여로최소한정.")

mc("S3C5-ADD-01", "③", "채권의 분류기준이 다른 하나는? ①복리채 ②할인채 ③고정금리채 ④이표채", "①만기까지이자를복리누적,②할인가발행/중간이자없이만기액면수취,④주기적쿠폰지급은이자지급/급부형태축이다.③은쿠폰율의고정/변동성이라는다른축.③.", "TARGET304쪽4보기동일. 할인채는단순현재할인가거래채권이아니라무이표발행형태정의.", "가격이액면미만인일반이표채도할인채라고부르는다른용례와구별.")
mc("S3C5-ADD-03", "④", "발행자콜권은없고투자자풋권만있는수의상환청구채권의설명중틀린것은? ①보유자가약정행사기간에정해진가격으로상환청구할수있다. ②같은현금흐름의일반채권가치에보유자풋가치를더해평가한다. ③신용등다른조건이같고시장수익률이오르면일반채권가격이낮아져정해진풋가격으로상환받는선택의경제적유인이커진다. ④금리하락시이풋권만으로발행자가중도상환을요구해보유자를낮은금리재투자에노출시킨다.", "풋권의행사자는보유자이므로발행자가행사한다는④가틀림. 만기시풋가치=max(K-B,0),일반채권가격B가수익률상승으로하락하면풋가치가증가한다.발행자콜을별도로가진혼합형은문제범위밖.", "TARGET304쪽4보기전체보존. 풋만있는채권·동일계약/신용·기타조건고정.", "원문의행사가능성이높아진다는표현은확률법칙이없어풋행사경제적유인증가로명시. 콜권을함께포함할가능성을배제.")
mc("S3C5-ADD-05", "③", "각조건에서채권설명중틀린것은? ①연1회양의고정쿠폰을후급하는영구채의연수익률5%일때맥컬리D는21년이다. ②금리에따라옵션행사와예상현금흐름이바뀌는옵션부채권은그변화를반영하는실효D를사용한다. ③쿠폰율과최초수익률이같은양의y인액면채를만기n만늘려비교하면D는체증적으로증가한다. ④같은y에서만기만다른무이표채는D가길수록볼록성이체증적으로증가한다.", "①D=(1+y)/y=21.②실효D=(Pminus-Pplus)/(2P0Δy)는금리충격별재평가현금흐름을사용.③액면연쿠폰채D=(1+y)/y×[1-(1+y)^(-n)]이고n차분은양수이나감소하므로체감증가.④무이표D=n,C=n(n+1)/(1+y)²로2차미분양수.③틀림.", "TARGET305쪽영구채/옵션D/만기D/볼록성4주제보존.③은초기액면채,④는같은수익률무이표채라는각각의비교범위.", "D만같거나크다는사실로임의현금흐름채권의C를전순위화할수없어④의비교대상을명시.③도극단할인채반례를피하는조건추가.")
mc("S3C5-ADD-06", "①", "양의고정현금흐름을갖는옵션없는채권의볼록성C=P″/P에관한설명이다. 틀린것은? ①같은수익률y에서만기만다른무이표채는D가짧을수록C가크다. ②동일한수정D와작은동일폭금리하락을비교하면2차근사에서C가클수록선형근사에추가되는가격상승률이크다. ③1차듀레이션근사는작은수익률변화에유용하며큰변화에서는곡률오차가커질수있다. ④기준수익률에서다른수익률로이동할때실제가격은기준접선에의한듀레이션선형가격보다높다.", "①무이표C=D(D+1)/(1+y)²이므로D증가에따라C증가하여반대다.②2차보정은.5CΔy².③테일러전개1차잔여는2차이상.④P″=Σt(t+1)CF/(1+y)^(t+2)>0이므로엄격볼록함수는기준점밖에서접선보다높다.①.", "TARGET306쪽4보기보존. 고정양급부·옵션없음·할인기저양수·기준점과다른수익률.", "원문항상낮다는④는변화0에서같으므로기준점밖으로한정.①임의채권간D-C순위를동일수익률무이표군으로명시.②큰변화까지C하나로순위보장하지않고2차근사조건.")
mc("S3C5-ADD-07", "②", "채권수익률이1%p상승했을때가격이3.14%하락하고수정듀레이션은3.22다. ΔP/P≈-DmodΔy+0.5C(Δy)²의2차근사를사용하여추정한볼록성C는? ①8 ②16 ③80 ④160", "-.0314=-3.22×.01+.5C×.01². 차이.0008=.00005C이므로C16.②.", "TARGET306쪽수치/4보기그대로. 수익률십진수,고차항무시한2차추정.", "한번의유한가격변화와D만으로진짜P″/P가정확히정해지는것은아니므로2차추정이라고명시.")
mc("S3C5-ADD-08", "④", "전통적인순수(불편)기대이론의단순화된전제로적절하지않은것은? ①투자자를위험중립으로본다. ②만기별채권은기간프리미엄을요구하지않는완전대체관계로본다. ③미래단기금리예상을장기금리에반영하되별도기간프리미엄은없다. ④제도적제약으로만기별시장이서로대체되지않는하위시장으로분할된다.", "무기간프리미엄하에서장기금리는예상단기금리경로를반영한다.④의비대체시장분할은그와다른시장분할가정이므로④.③은예상이반영된다는말이지실현금리를완벽히맞춘다는말이아니다.", "TARGET306쪽위험중립/대체관계/금리예상/시장분할4주제보존. 수익률기간평균관계는전통교재근사모형.", "원문③미래금리를정확히예측할수있다는완전예견은기대이론필수조건이아니므로불편기대/기간프리미엄부재로최소교정.")
mc("S3C5-ADD-09", "①", "3년물국채수익률4%,같은만기회사채7%다. 경기불황전환과함께회사채신용스프레드확대를예상하여신용노출을줄이고낮은수익률을감수하려한다. 금리위험등다른요인을통제할때교체방향과명칭은? ①국채매수·Yield Give Up Swap ②국채매수·Yield Pick Up Swap ③회사채매수·Yield Give Up Swap ④회사채매수·Yield Pick Up Swap", "높은7%회사채를매도하고낮은4%국채를매수하여약정수익률을포기하는교체이므로give up. 회사채스프레드확대에따른가격하락노출을줄이므로①.", "TARGET306쪽두수익률/4조합보존. 스프레드확대는전망조건이지경기불황만으로보장되는결론아님.", "원문의경기와스프레드를기계적필연관계로일반화하지않고명시적전망하에정의문항으로유지.")
mc("S3C5-ADD-10", "①", "우상향수익률곡선이시간경과중유지되어장기채의잔존기간이짧아지면곡선상수익률이낮아진다. 쿠폰·시간경과·액면수렴효과와분리한수익률하락의가격상승기여를얻으려는장기구간전략의교재상명칭은? ①롤링효과 ②숄더효과 ③면역전략 ④만기보유전략", "TARGET298쪽은장기구간ΔA를롤링,중단기급경사ΔB를숄더라정의한다.307쪽질문에장기구간을명시하면①. y(T-h)<y(T),∂P/∂y<0이므로롤다운가격기여는양수.", "TARGET307쪽질문/4보기와298쪽실제도표교차확인. 명칭은교재분류이며우상향유지/고정현금흐름.", "원문은장기/중단기구간을특정하지않아①②구별근거가부족하다. 장기구간을최소추가. 쿠폰채시간경과총가격상승또는항상수익보장은제외.")

mc("MOCK-1-Q076", "③", "액면10000원,만기2년인무이표할인채를매입한다. 연단위할인수익률은10%이며중간쿠폰은없다. 부도없이계약대로지급될때1년뒤와2년뒤현금흐름은? ①1000원,11000원 ②1000원,12100원 ③0원,10000원 ④0원,12100원", "무이표할인채는중간쿠폰0,만기액면10000원.10%는현재가격10000/(1.1)²에반영될뿐만기급부를12100으로늘리지않음.③.", "TARGET모의21쪽실제4보기전체확인;부도없음.", "원문의표면이율10%할인채혼합표현은연할인수익률10%로교정. 만기급부/4보기유지.")
mc("MOCK-1-Q079", "④", "옵션없는고정양현금흐름채권의가격변동성설명중옳은것은? ①쿠폰율c와최초수익률y0=c>0가같은액면채의만기만비교하면동일금리변화에대한가격변동폭은만기가길수록작다. ②같은액면채군의가격변동폭은만기에따라체증적으로증가한다. ③만기·수익률등다른조건이같을때쿠폰율이높을수록동일한작은수익률변화의가격변동률이크다. ④같은채권·같은기준수익률에서동일폭금리하락의가격상승폭은금리상승의하락폭보다크다.", "①②초기액면군의변동폭=|1-c/y|[1-(1+y)^(-n)]이므로만기에따라체감증가.③쿠폰이높으면일찍받는현금흐름의PV비중이증가해D가작아지고작은변화의가격변동률도작다.④양현금흐름P″>0으로성립.④.", "TARGET모의22쪽4보기전체확인.변화후수익률양수.③는미소변화율비교.", "원문만기와민감도무조건관계를초기액면군으로한정;가격변동폭/변동률의혼동을구분.")
mc("MOCK-1-Q080", "①", "우상향곡선이예상대로유지되는기간에쿠폰·액면수렴과분리한롤다운가격효과를활용하고자한다. 수익률곡선타기설명중틀린항목은? 가.투자기간보다만기가짧은채권만을이용한다. 나.장기구간롤링과중단기구간숄더효과를이용한다. 다.유동성프리미엄이반영된우상향형태의유지가예상대로실현될때롤다운기여를기대한다. 라.만기전에매도하여가격효과를실현하는전략이다. ①가 ②나 ③다 ④가·다", "만기전에매도해야잔존기간단축에따른수익률곡선상하락을활용하므로만기는투자기간보다길다.가틀림.나다라는각명시된조건에서전략정의와일치하므로①.", "TARGET모의22쪽가나다라와4조합모두확인;298쪽장기/중단기교재명칭연결.", "원문다의유동성프리미엄설이타당하면항상수익이라는확대는곡선유지예상과실현조건으로한정. 원해설투자기간9년인데1년후매도라는시간혼동은채택하지않음.")
mc("MOCK-1-Q081", "②", "3년국채4%,3년회사채7%이고경기불황전환과함께회사채신용스프레드확대를예상한다. 낮은수익률을감수하며신용노출을줄이는교체방향과명칭은? ①국채매수·회사채매수/Yield Give Up ②국채매수·회사채매도/Yield Give Up ③국채매도·회사채매도/Yield Pick Up ④국채매도·회사채매수/Yield Pick Up", "7%회사채를팔고4%국채를사는것이수익률포기give up이므로②. 기대하는것은신용스프레드확대노출회피이며경기예측만으로확정수익이아님.", "TARGET모의22쪽4매매조합전체확인;동일만기·금리위험등통제.", "원해설반대호황의경우더낮은수익률채권을매수라고쓴부분은회사채7%매수이므로오류. 원문불황질문의숫자·정답②보존.")
mc("MOCK-2-Q076", "④", "전환사채액면10000원,전환가격5000원,대상주가6500원,CB시장가격15000원이다. 전환괴리율은(CB가격-전환가치)/전환가치로정의하고퍼센트를소수첫째자리까지반올림한다. 틀린것은? ①패리티130%,패리티가격13000원 ②전환프리미엄+2000원 ③괴리율15.4% ④시장가격에음의전환프리미엄이반영되어있다.", "전환주식수10000/5000=2,전환가치2×6500=13000.패리티6500/5000=130%.프리미엄15000-13000=+2000,괴리율2000/13000=15.384615...%→15.4.④음의프리미엄이틀림.", "TARGET모의48쪽전체입력/4보기직접확인;정의·반올림만명시.", "원문③15.3%는통상반올림불일치여서15.4%로최소교정. CB가항상더안전해서프리미엄항상양수라는해설일반화는승인하지않음.")
mc("MOCK-2-Q078", "③", "다음채권설명중틀린것은? ①양의쿠폰율과수익률이같은액면연쿠폰채의만기를늘리면맥컬리D는체감적으로증가한다. ②옵션행사로예상현금흐름이금리에따라변하는채권은이를반영하는실효D가적절하다. ③같은수익률의무이표채를만기만달리비교하면D증가시C는가속적으로감소한다. ④연1회후급고정쿠폰영구채의수익률5%일때맥컬리D는21이다.", "①D=(1+y)/y[1-(1+y)^(-n)]는만기에따라체감증가.②실효D는충격별현금흐름재평가.③무이표C=D(D+1)/(1+y)²는가속증가이므로틀림.④1.05/.05=21.③.", "TARGET모의48쪽4보기전체확인;옵션없는양현금흐름과각비교조건.", "원문일반회사채만기/D/C관계를조건없이전체채권에적용하지않도록①액면군③무이표군명시.4주제유지.")
mc("MOCK-2-Q079", "②", "옵션없는양의고정현금흐름을가진3년이표채의현재수정D는2.6이다. 수익률변화는1%p이고고정현금흐름을같은복리방식으로할인한다. 실제가격변화의옳은설명은? ①금리하락시정확히2.6%상승 ②금리하락시2.6%보다더상승 ③금리상승시정확히2.6%하락 ④금리상승시2.6%보다더하락", "접선변화율=-DmodΔy. 양현금흐름P″>0이므로실제P는기준점밖에서접선P보다높다. 하락Δy=-.01이면실제상승률>+.026,상승시하락률절댓값<.026.②.", "TARGET모의48쪽4보기수치모두확인;기준점밖,옵션없음,할인기저양수.", "원문1%의수익률변화를1%p로명시. 옵션부음볼록성채권까지일반화하지않음.")
mc("MOCK-2-Q080", "③", "다음수익률기간구조설명중틀린것은? ①무기간프리미엄의순수기대이론만으로수익률곡선타기의확실한초과수익을보장할수없다. ②양의장기유동성프리미엄을가정하는교재의유동성선호이론에서는그프리미엄은양수다. ③편중기대모형에서양의유동성프리미엄이있으면미래단기금리하락기대의크기와관계없이장기수익률은단기수익률보다항상높다. ④동일복리기준으로매끄럽게엄격우상향하는현물이율곡선에서,각만기의한계선도금리>그만기의현물이율이며중간쿠폰이양수인채권의만기수익률은최종만기현물이율보다낮다.", "③기대단기금리평균하락분이프리미엄보다크면장기금리가단기보다낮아져반례.④연속복리표현f(T)=s(T)+Ts′(T)>s(T);중간현금흐름의현물이율은s(T)보다낮아모든현금흐름을s(T)로할인하면실제가치보다작으므로이를맞추는단일YTM은s(T)보다낮다.①확정초과수익보장불가와②가정의정의는맞다.", "TARGET모의49쪽4주제대조.④순간선도/동일복리/우상향현물/양쿠폰가정명시.", "원문①전략자체가불가능은기대초과수익보장불가로최소교정.④이자율상승구간이라는모호한축을현재단면의우상향현물곡선으로정의하며복리환산기준일치.")
mc("MOCK-2-Q081", "④", "고정현금흐름과평탄수익률곡선에서목표투자기간H에대한작은평행금리변화의가격효과와재투자효과를1차상쇄하려한다. 자산PV를목표에맞추고맥컬리D=H로구성·재조정하는전략은? ①Barbell형채권운용 ②Bullet형채권운용 ③롤링효과운용전략 ④전통적면역전략", "목표시점가치V_H(y)=P(y)(1+y)^H의로그미분은P′/P+H/(1+y)=(H-D)/(1+y). D=H이면1차금리민감도가0이므로④. 바벨/불릿은현금흐름배치형태로서그명칭만으로PV/D매칭을보장하지않음.", "TARGET모의49쪽4전략선택지보존. 작은평행이동·고정현금흐름·신용위험없음·필요시재조정.", "원해설모든시장수익률변동무관최선수익실현이라는과도한문구는1차국소면역으로교정;비평행곡선/큰충격/신용위험완전면역아님.")

concept("NOTE-S3C5-Q014", "낮은, 높은", "발행가격·만기·신용조건이같고옵션가치가양수라고하자. 보유자에게전환권을더해주는CB는일반사채보다(낮은/높은)쿠폰으로,발행자에게콜권을주는콜부사채는(낮은/높은)쿠폰으로같은발행가격을맞출수있는가?", "CB가치=채권가치+보유자전환옵션,콜부가치=일반채권가치-발행자콜옵션. 쿠폰증가에따라일반채권가치는증가하므로같은발행가격을맞추려면CB쿠폰하락,콜부쿠폰상승.낮은/높은.", "TARGET노트65쪽두비교전체확인;다른특징동일·양옵션가치·쿠폰조정만으로같은발행가치맞춤.", "실제시장CB와임의회사채의관측쿠폰을조건없이비교하는단정을등가조건가격관계로교정.")
concept("NOTE-S3C5-Q016", "복수가격낙찰방식, 단일가격낙찰방식, 차등가격낙찰방식", "낮은응찰금리부터물량을배정한후, 낙찰자각자의응찰금리를적용하는방식,최고낙찰금리를모든낙찰분에통일하는방식,구간을나누어각구간의최고금리를적용하는방식을순서대로쓰시오.", "공식낙찰예시의Conventional/Dutch/Differential-Price가각각복수가격/단일가격/차등가격에대응. 낮은금리부터물량배정만으로는Conventional을구별할수없어첫방식의각자금리조건이필요.", "TARGET노트65쪽실제3빈칸확인;낙찰순서와낙찰대금산정구분.", "원문첫빈칸은낮은금리부터순차낙찰이라는공통요소만있어불충분하므로각응찰금리적용을최소보완.", "FB007")
concept("NOTE-S3C5-Q017", "IDM", "국채딜러간경쟁매매로거래되는장내시장을교재의약칭으로고르면? (IDM / IDB)", "IDM은Inter Dealer Market으로시장,IDB는Inter Dealer Broker로중개자다. KRX국채전문유통시장은국채딜러간매매용장내시장이다.", "TARGET노트65쪽실제발문/선택지확인. 현재KRX표기는KTS도사용.", "OCR누락발문을이미지에서복원;IDM과현재KTS명칭을구분.", "FB004")
concept("NOTE-S3C5-Q018", "O", "국고채전문딜러가되려면국채에대한투자매매업(인수업포함)인가를갖춘국채딜러중PPD선행등규정상요건을충족하고재정경제부장관의별도지정을받아야한다. O/X?", "규정2조국채딜러인가/장관지정정의,29조PPD선행과지정요건으로O. 인가만받으면자동PD가되는것이아님.", "TARGET노트65쪽전체발문확인;2026-02-23시행규정.", "기획재정부명칭을재정경제부로교정하고PPD선행보완.", "FB003", kind="ox")
concept("NOTE-S3C5-Q019", "8%", "2026-10-13기준국고채발행규정30조1항에명시된기본인수의무는매월각만기별입찰공고상발행예정물량의몇%이상인가? (2항실적산정특례와3항장관조정권한은별도.)", "30조1항8%이상. 교재10%와다름. 지표종목별이라는원문표현도현행각만기별공고물량과구별.", "TARGET노트66쪽빈칸전체확인;실제특정입찰조정공고비율이아닌규정본문기본값.", "원정답10%→8%교정과기준분모변경을명시.", "FB003")
concept("NOTE-S3C5-Q023", "X", "KRX국채전문유통시장(IDM/KTS)에서거래되는국고채의매매수량단위는액면5억원이다. O/X?", "KRX공식안내는10억원정수배이므로X. 노트66쪽해설실제이미지도10억원이며packetOCR70억원은오류.", "TARGET노트66쪽실제이미지정답과발문확인.", "OCR70억원→10억원복원. 질문5억원은틀린진술로보존.", "FB004", kind="ox")
concept("NOTE-S3C5-Q026", "적다", "옵션없는양의고정현금흐름채권을같은기준수익률에서같은폭으로금리상승/하락시킨다. 상승에따른가격하락폭은하락에따른가격상승폭보다(크다/적다)?", "P″>0이므로P(y-h)+P(y+h)>2P(y),따라서P(y)-P(y+h)<P(y-h)-P(y).적다.", "TARGET노트66쪽실제완전발문복원;h>0,모든할인기저양수.", "원문같은폭조건생략을보완하고옵션부음볼록성예외배제.")
concept("NOTE-S3C5-Q027", "작아진다", "만기·수익률·지급주기·신용조건이같은옵션없는고정쿠폰채를비교한다. 쿠폰율이높을수록작은동일폭수익률변화에대한가격변동률의절댓값은(커진다/작아진다)?", "쿠폰이높으면일찍받는현금흐름의PV가중치가커져맥컬리및수정D가작아진다. |ΔP/P|≈Dmod|Δy|이므로작아진다.", "TARGET노트67쪽2선택지그대로. 양의할인기저·변화미소·가격변동률.", "절대원화가격변동폭과민감도변동률의혼동을후자로명시.")
concept("NOTE-S3C5-Q028", "낮을수록, 길수록, 낮을수록", "기준은옵션없는연쿠폰5%·만기5년·수익률5%채권이다. 각각독립적으로쿠폰5→3%,만기5→10년,수익률5→3%로바꾸어맥컬리D가증가하는방향을빈칸에쓰면, 쿠폰이( ),잔존만기가( ),수익률이( )이다.", "PV가중평균D는기준4.5459505,쿠폰3%4.7017445,만기10년8.1078217,수익률3%4.5680605로모두증가.따라서낮을수록/길수록/낮을수록.", "TARGET노트67쪽3빈칸보존. 기준·각각독립비교명시.", "임의깊은할인채의만기증가가항상D를높인다는잘못된일반화를막고평가가능한비교조건보완.")
concept("NOTE-S3C5-Q029", "현금흐름 현재가치 가중평균 회수기간, 작은 금리변화에 대한 상대가격 민감도", "듀레이션의두경제적의미는? 맥컬리D의시간해석과수정D의가격해석을구분하여쓰시오.", "Dmac=ΣtPV(CF_t)/P는쿠폰과원금전체현금흐름의PV가중평균시점. 연복리Dmod=Dmac/(1+y)=-P′/P는작은수익률변화에대한상대가격민감도이며통계적표준편차와다르다.", "TARGET노트67쪽2의미보존. 고정양급부·동일연복리.", "원문투자원금의가중상환기간은쿠폰현금흐름을누락해전체급부PV가중기간으로교정. 가격변동성은확률표준편차가아닌금리민감도.")
concept("NOTE-S3C5-Q030", "4%, 10년", "연1회옵션없는채권들에동일수익률5%와같은신용·비용을가정한다. 작은금리하락의가격상승률을듀레이션으로높이려면쿠폰(4%/8%)·만기(3년/10년)중어느조합인가?", "Dmac는4%3년2.88438,4%10년8.35959,8%3년2.79205,8%10년7.54193. 수정D는공통1.05로나누므로순서같고4%10년최대.", "TARGET노트67쪽4/8·3/10실제이미지확인. 같은5%에서독립재계산.", "원문강한하락/투자수익극대화는큰충격고차항·다른위험을무시하므로작은금리하락의가격효과목적으로한정.")
concept("NOTE-S3C5-Q031", "O", "옵션없고중간양의쿠폰과만기원금이있는채권의맥컬리D는잔존만기보다짧다. 중간지급없이전현금흐름을만기한번에받는무이표·복리형만기일시지급채의D는잔존만기와같다. O/X?", "양의PV가중평균시점은최대시점보다앞선양의가중치가있으면엄격히작고,만기한시점에만가중치가있으면그시점과같으므로O.", "TARGET노트67쪽2진술전체보존;고정현금흐름·맥컬리D.", "원문의만기일시상환채는원금만일시상환하는이표채도포함할수있어전급부만기일시지급으로교정.", kind="ox")
concept("NOTE-S3C5-Q036", "28계약 매도", "현물채권포트폴리오의시장가치100억원,수정D2.8이다. 채권선물1계약의액면은1억원이며헤지계산에사용하는계약가격기준금액도1억원,유효수정D10이다. 현물·선물에같은평행금리충격이작용하고전환계수는1이라고단순화할때1차금리헤지계약수와방향은?", "현물달러D=100억×2.8,선물계약당=1억×10. N=280/10=28. 현물매수의금리상승손실을상쇄하려면선물매도28계약.", "TARGET노트68쪽100억/2.8/10/액면1억입력전체보존. 선물DV01등가금액/전환계수/평행변동명시.", "원문액면만으로선물시장가격노출이결정되지않아액면가와계약가격기준금액일치및전환계수1조건보완. 실제국채선물상품사양주장아님.")
concept("NOTE-S3C5-Q037", "O", "동일한양의수익률y로평가하는무이표채를만기만늘려비교하면,맥컬리D가커질수록C=P″/P는체증적으로증가한다. O/X?", "D=T,C=T(T+1)/(1+y)². D에대한C의이차미분2/(1+y)²>0으로O.", "TARGET노트68쪽D-C관계O/X보존. 동일수익률무이표군.", "원문임의채권의D-C관계전면단정은현금흐름분산차이반례가있어비교군명시.", kind="ox")
concept("NOTE-S3C5-Q038", "O", "초기가격과수정D가같은옵션없는두채권에서다른조건이같고같은작은수익률충격을비교한다. 2차테일러근사에서는C가큰채권이0이아닌금리상승·하락모두에서더높은근사가격을갖는다. O/X?", "ΔP/P≈-DmodΔy+.5CΔy². 가격/D/Δy가같으면가격차이는.5P(C1-C2)Δy²>0이므로O.", "TARGET노트68쪽동일D·높은C·금리상하비교보존. 초기동일가격·수정D·고차항무시.", "원문항상높은가격/무조건유리라는해설은초기가격과고차항·옵션·추가비용조건없이성립하지않으므로2차비교로한정.", kind="ox")
concept("NOTE-S3C5-Q040", "채무불이행위험(신용위험), 비체계적 위험", "원리금전부또는일부를못받는위험은( )이다. 그원인중경기공통요인을제거한특정발행자만의우발적부분은(체계적위험/비체계적위험)이다.", "원리금미지급위험은default/credit risk. 이중공통요인과무관한개별발행자잔차성분을정의상비체계적위험이라부른다. 모든신용위험이비체계적이라는뜻은아님.", "TARGET노트68쪽두빈칸과정답형식보존;개별잔차성분한정.", "원문신용위험전체=비체계적단정은경기동반부도등체계성분을누락. 두번째분류대상을개별발행자고유부분으로최소교정.", "FB006")
concept("NOTE-S3C5-Q044", "롤링효과, 숄더효과", "우상향곡선이유지될때잔존기간감소의수익률하락효과를활용하는전략에서교재가장기채구간효과와중·단기급경사구간효과를부르는명칭은순서대로무엇인가?", "P3 298실제도표ΔA장기=롤링,ΔB중단기=숄더. 노트69두빈칸에동일하게대응.", "TARGET노트69쪽및P3 298도표;교재용어정의.", "원금보장·총수익보장이아닌교재구간별명칭.")
concept("NOTE-S3C5-Q045", "4%, 10년", "동일수익률5%의옵션없는연쿠폰채에서작은금리하락직후가격상승률을높이려한다. 다른신용·비용이같을때쿠폰(4%/8%)·만기(3년/10년)중가장긴듀레이션조합은?", "PV가중D는(4%,3년)2.88438,(4%,10년)8.35959,(8%,3년)2.79205,(8%,10년)7.54193. 4%·10년이최대여서1차상승률이가장크다.", "TARGET노트69쪽두선택쌍그대로;공통수익률5%추가.", "원문채권수익률극대화는금리하락시요구수익률이낮아진다는점과혼동되어가격상승률로교정. 모든위험/보유수익전체최대화뜻아님.")
concept("NOTE-S3C5-Q046", "롤링효과", "시간중유지되는우상향수익률곡선의장기완만구간에서잔존기간감소에따른수익률하락이기여하는가격효과를얻고자만기전매매하는교재상전략명은?", "장기완만구간롤다운을P3 298과NOTE69는롤링효과라부르며중단기급경사구간숄더와구분. 고정잔여현금흐름의y하락기여는∂P/∂y<0으로양.", "TARGET노트69쪽발문/해설및P3 298도표대조.", "장기구간을명시하여숄더와중복답방지. 쿠폰채시간경과총가격상승을보장하지않도록수익률하락기여로한정.")
concept("NOTE-S3C5-Q049", "전통적 면역전략, Passive", "작은평행금리변화에대해목표투자기간H와채권포트폴리오맥컬리D를일치시키고현재가치를목표에맞추는전략은( )이며,재량적금리예측으로초과수익을노리지않는교재분류상(Active/Passive)전략이다.", "목표시점가치P(y)(1+y)^H의1차민감도는(H-D)/(1+y)이므로D=H일때상쇄되는전통적면역. 수익률예측없이목표방어를하는운용목적은Passive이며시간경과재조정이필요할수있다.", "TARGET노트69쪽실제발문복원;고정현금흐름·평탄금리/작은평행변화·PV매칭.", "원문채권의잔존만기와D일치는투자기간과D일치로교정. 채권잔존만기=D이면무이표라는다른개념이므로오류기록.")

mc("S3C5T11-SUP-03", "②", "옵션없는연쿠폰채권의현재수익률은모두5%이고신용등다른조건은같다. 작은평행금리하락의가격상승률을듀레이션으로높이려면어느조합인가? 가.쿠폰5%,나.쿠폰8%,다.만기3년,라.만기10년. ①가·다 ②가·라 ③나·다 ④나·라", "Dmac는5%3년2.85941,5%10년8.10782,8%3년2.79205,8%10년7.54193. 공통수익률로수정D순서도같아가·라가최대이므로②.", "TARGET278쪽쿠폰5/8와만기3/10및4조합보존. 동일수익률5%,연쿠폰직후,작은충격.", "전임보류의만기-D무조건관계를공통수익률하의개별현금흐름재계산으로해소. 큰금리하락의총투자수익극대화보장아님.")
mc("S3C5T13-SUP-01", "④", "옵션없는양의고정현금흐름채권을연복리할인한다. 틀린것은? ①같은채권의수익률이하락하면C=P″/P는증가한다. ②기준수익률과다른곳에서실제가격은기준접선듀레이션가격보다높다. ③같은수익률에서무이표채의만기를늘리면맥컬리D증가에따라C는체증적으로증가한다. ④같은만기·수익률에서중간양의쿠폰율을낮추면C가감소한다.", "①C=Ew[t(t+1)]/(1+y)², y상승시늦은급부의PV가중치가감소하고분모는증가해C감소.②엄격볼록함수의접선부등식.③C=D(D+1)/(1+y)².④쿠폰하락이면만기원금의PV비중이증가해평균t(t+1)가증가하므로C가커져거짓.④.", "TARGET285쪽4보기주제보존;①②④동일고정급부·양의쿠폰/원금·기저1+y>0,③동일수익률무이표군.", "원문②항상높음은변화0에서같으므로기준점밖으로수정.③임의채권간D-C전순위단정은비교군명시. 원문4보기삭제없음.")
mc("S3C5T14-CORE", "②", "도표의3·4·5년국채수익률은3.7·3.9·4.0%,회사채는7.0·7.6·8.0%다. 동일만기의회사채-국채수익률차이를이문항의신용스프레드로정의한다. 틀린것은? ①5년스프레드는4.0%p다. ②다른조건이같고경기호전으로기업부도위험과요구위험보상이줄어드는경우에도신용스프레드는더욱확대되는방향이다. ③같은발행주체·신용등비만기조건을맞춘채권의만기별수익률을연결한것은수익률곡선이다. ④회사채5년과4년기간스프레드는.4%p다.", "①8-4=4%p,④8-7.6=.4%p.③기간구조정의.②신용위험보상이줄어드는조건은스프레드축소방향이므로반대다. 연준연구도스프레드확대와침체위험의관련을보고하지만그통계만으로모든국면을확정하지않는다.", "TARGET287쪽실제도표6수치와4보기직접확인.스프레드는회사채국채차이라는조작적정의이며유동성/세금등포함가능.", "원문%를%p로교정. 호황이면언제나축소/불황이면언제나확대라는인과단정을②명시된위험감소시나리오로한정하며원문의경기/스프레드판단범위유지.", "FB008")
mc("S3C5T16-CORE", "④", "전통적기간구조이론설명중틀린것은? ①순수불편기대이론은기간·유동성프리미엄0을가정한다. ②기대단기금리성분이일정할때장기일수록양의프리미엄이증가하는유동성선호가정은우상향곡선을설명한다. ③기대금리성분과기간프리미엄이결합된편중기대모형은전반상승후하강하는낙타형도설명할수있다. ④투자자가선호만기를벗어나도록보상을받으며기간프리미엄부호가수급에따라달라질수있는설명은만기간대체가전혀없는엄격한시장분할가정그자체이다.", "①무프리미엄정의.②y(T)=일정기대성분+증가프리미엄이면우상향.③같은분해에서기대성분의변화가프리미엄을상쇄하거나우세하면낙타형도가능.④보상에따라선호만기를떠날수있는것은preferred habitat,엄격분할은그대체를허용하지않으므로④.", "TARGET292~294쪽4이론주제대조. 교재의편중기대는기대성분+기간프리미엄모형으로정의.", "원문④기간프리미엄부호만으로이론이유일구별되지않는문제를선호만기이탈대체가능성조건을추가해교정.②가장잘설명이라는무정의우열표현대신동일기대조건을명시.")
mc("S3C5T16-SUP-03", "②", "편중기대모형을만기별수익률y(T)=기대단기금리평균성분a(T)+유동성프리미엄L(T)으로근사한다. 틀린것은? ①순수기대성분과유동성프리미엄의결합으로볼수있다. ②a와L의합은우상향·우하향·수평형은가능하지만낙타형은설명할수없다. ③만기에따른a의하락분과L의증가분이각구간에서같으면수평이다. ④각구간a하락분이L증가분보다크면우하향한다.", "Δy=Δa+ΔL.③합0이면수평④합음수이면하향. 낙타형예로만기1·2·3의a=(4,5,3)%,L=(0,.2,.4)%이면y=(4,5.2,3.4)%로상승후하락이므로②틀림.①분해정의.", "TARGET295쪽4보기전체보존. 미래한시점금리와기간평균을구분하고각구간변화량으로조건명시.", "원문하락예상분과프리미엄수준을직접비교한모호성을동일만기구간성분변화량비교로교정. 하나의원하는곡선을새문항으로대체하지않고원문4추론유지.")
